CREATE COLUMN TABLE "TEST_AP"."OIGW" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItmsGrpCod" SMALLINT CS_INT NOT NULL , "WhsCode" NVARCHAR(8) NOT NULL , "DftBinAbs" INTEGER CS_INT, "DftBinEnfd" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
